# ---------------------------------------------------------------
# NFL 查表引擎
# ---------------------------------------------------------------
@st.cache_resource
def load_charts():
    raw = json.loads(NFL_JSON)
    out = {}
    for t, lv in raw.items():
        c = {}
        for k, (ar, d) in lv.items():
            ar = np.array(ar, float); ly = np.log(np.array(d, float))
            ly = np.maximum.accumulate(ly)
            ar, ix = np.unique(ar, return_index=True); ly = ly[ix]
            c[float(k)] = (ar, ly, lambda x, ar=ar, ly=ly: np.interp(x, ar, ly))
        out[int(t)] = c
    return out


def contour_long(chart, level, AR):
    """等值線在長寬比 AR 時對應之長邊尺寸(mm);第二值=是否為外推"""
    ar, ly, f = chart[level]
    if ar[0] <= AR <= ar[-1]:
        return float(np.exp(f(AR))), False
    if AR < ar[0]:
        n = min(6, len(ar)); p = np.polyfit(ar[:n], ly[:n], 1)
        return float(np.exp(np.polyval(p, AR))), True
    n = min(8, len(ar)); p = np.polyfit(np.log(ar[-n:]), ly[-n:], 1)
    s = max(0.9, min(1.3, p[0]))
    return float(np.exp(ly[-1] + s * np.log(AR / ar[-1]))), True


def lookup_nfl(t, long_mm, short_mm):
    """回傳 (NFL kPa, 備註清單)"""
    chart = load_charts()[t]
    notes = []
    xmax, ymax = CHART_LIMITS[t]
    if long_mm > xmax or short_mm > ymax:
        notes.append("尺寸超出圖表範圍")
    AR = long_mm / short_mm
    lv = sorted(chart)
    pts = [(k,) + contour_long(chart, k, AR) for k in lv]
    for (k1, d1, e1), (k2, d2, e2) in zip(pts, pts[1:]):
        if d1 >= long_mm >= d2:
            w = np.log(d1 / long_mm) / np.log(d1 / d2)
            val = float(np.exp(np.log(k1) + w * (np.log(k2) - np.log(k1))))
            if e1 or e2:
                notes.append("鄰近等值線已超出圖表邊界,以外推補足(誤差略增)")
            return val, notes
    if long_mm > pts[0][1]:           # 比最低等值線更大 -> 低於最低 NFL
        (k1, d1, _), (k2, d2, _) = pts[0], pts[1]
        s = np.log(k2 / k1) / np.log(d2 / d1)
        val = float(np.exp(np.log(k1) + s * np.log(long_mm / d1)))
        notes.append(f"低於圖表最低等值線({k1:g} kPa),外推")
        return val, notes
    k_top = pts[-1][0]
    notes.append(f"高於圖表最高等值線({k_top:g} kPa),以 {k_top:g} kPa 取代(偏保守)")
    return k_top, notes


# ---------------------------------------------------------------
# 變形:Appendix X1
# ---------------------------------------------------------------
def deflection_x1(long_mm, short_mm, q_kpa, t_mm, E_kpa=71.7e6):
    ab = min(long_mm / short_mm, 5.0)
    r0 = 0.553 - 3.83 * ab + 1.11 * ab**2 - 0.0969 * ab**3
    r1 = -2.29 + 5.83 * ab - 2.17 * ab**2 + 0.2067 * ab**3
    r2 = 1.485 - 1.908 * ab + 0.815 * ab**2 - 0.0822 * ab**3
    arg = q_kpa * (long_mm * short_mm) ** 2 / (E_kpa * t_mm**4)
    if arg <= 1.0:
        return 0.0
    x = np.log(np.log(arg))
    return t_mm * np.exp(r0 + r1 * x + r2 * x**2)


